    "lc-frontiere": {
     "name": "The margins: Escalante, Bustamante",
     "summary": "The violence of Michoacán and Mayan Guatemala: Latin American cinema of borders and indigenous peoples.",
     "traits": [
      "Violence of the margins",
      "Indigenous languages",
      "Radical realism",
      "Southern festivals"
     ]
    }
